ommand": "st0x-liquidity-client --env production debug fail-usdc-transfer <id> --reason \"<reason>\"", "description": "Force a USDC bridge stuck before its burn into Failed. The bot accepts it for an Alpaca to Base bridge whose withdrawal completed, or a Base to Alpaca bridge whose vault withdrawal was not sent. If the Alpaca withdrawal completed, the guard stays held until reconcile-usdc settles the funds. After a Base to Alpaca vault withdrawal, the bot refuses it: stop the bot, run the offline stox fail-usdc-transfer, and move the wallet USDC back by hand.", "whenToUse": "A USDC bridge is stuck before its CCTP burn and must be terminalized. Check the transfer and verify on-chain that no burn landed first.", "appliesTo": "USDC bridge (pre-burn stuck)", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug reconcile-equity <mint|redemption> <id> --reason \"<reason>\"", "description": "Mark a terminally-failed equity transfer Reconciled after handling residue manually.", "whenToUse": "An equity transfer is in a terminal failure and its residue was settled out-of-band (bookkeeping).", "appliesTo": "Failed equity mint / redemption", "mode": "requires-bot"}, {"command": "st0x-liquidity-client --env production debug reconcile-usdc <id> --reason <funds-moved-manually|deposit-credited-offline>", "description": "Mark a failed USDC bridge Reconciled after its funds were settled manually.", "whenToUse": "A USDC bridge failed after its funds left the source venue, and they were settled out-of-band.", "appliesTo": "Post-burn USDC failure (DepositFailed, post-burn BridgingFailed, or BaseToAlpaca ConversionFailed)", "mode": "requires-bot"}]}, {"object": "position", "commands": [{"command": "st0x-liquidity-client --env production debug position release-hedge <symbol> --order-id <order-id> --reason \"<reason>\"", "description": "Clear a position's pending offchain order pointer so hedging can retry.", "whenToUse": "A position is wedged on a hedge order